     pub fn circuit<'ctx>(&self, domain: u8, inputs: &[Var<'ctx, Scalar>]) -> Var<'ctx, Scalar> {
+        #[cfg(feature = "formal-observer")]
+        {
+            let call = inspection::start(domain, inputs);
+            let note_call = note_inspection::start(domain, inputs);
+            let observe = |block, after, state: &[Var<'ctx, Scalar>]| {
+                inspection::state(&call, block, after, state);
+                note_inspection::state(&note_call, block, after, state);
+            };
+            let output = if inputs.len() <= 2 {
+                self.small.hash_observed(domain, inputs, |value| Var::native(value.clone()), &observe)
+            } else {
+                self.wide.hash_observed(domain, inputs, |value| Var::native(value.clone()), &observe)
+            };
+            inspection::finish(call, &output);
+            note_inspection::finish(note_call, &output);
+            return output;
+        }
+        #[cfg(not(feature = "formal-observer"))]
+        {
         let output = self.hash(domain, inputs, |value| Var::native(value.clone()));
         output
